const list = document.getElementById('list');
const statusEl = document.getElementById('status');
let latest = 0;
async function load(q) {
  const seq = ++latest;
  try {
    const res = await fetch('/users' + (q ? '?q=' + encodeURIComponent(q) : ''));
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const rows = await res.json();
    if (seq !== latest) return; // 古い応答で新しい結果を上書きしない
    list.replaceChildren(...rows.map((u) => Object.assign(document.createElement('li'), {textContent: u.name + ' <' + u.email + '>'})));
    statusEl.textContent = rows.length === 0 ? '該当するユーザーはいません' : '';
  } catch (e) {
    if (seq !== latest) return;
    list.replaceChildren();
    statusEl.textContent = '一覧を取得できませんでした。再度お試しください';
  }
}
document.getElementById('q').addEventListener('input', (e) => load(e.target.value.trim()));
load('');

content.text:
`docs/BRIEF.md` の依頼にはまだ対応できていません。このセッションではファイルの編集と実行に使うツールが無効で、`Write` を呼ぶとエラーになりました。使えるのは読取りと検索だけです。そのため `public/users.js` は変更しておらず、画面での動作確認もできていません。

**現状**
- `public/users.html` には絞り込み用の入力欄 `#q` と、表示用の `<p id="status" role="status">` がすでにあります。
- `public/users.js` は入力のたびに `GET /users?q=` を呼び、一覧は更新します。
- 0件のときの「該当するユーザーはいません」は出しません。
- 取得に失敗した場合の処理もありません。
- 入力が速いと、古いリクエストの応答が後から届き、新しい結果を上書きするおそれがあります。

**変更案（`public/users.js` の全置換）**
```js
const list = document.getElementById('list');
const statusEl = document.getElementById('status');
let latest = 0;
async function load(q) {
  const seq = ++latest;
  try {
    const res = await fetch('/users' + (q ? '?q=' + encodeURIComponent(q) : ''));
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const rows = await res.json();
    if (seq !== latest) return; // 古い応答で新しい結果を上書きしない
    list.replaceChildren(...rows.map((u) => Object.assign(document.createElement('li'), {textContent: u.name + ' <' + u.email + '>'})));
    statusEl.textContent = rows.length === 0 ? '該当するユーザーはいません' : '';
  } catch (e) {
    if (seq !== latest) return;
    list.replaceChildren();
    statusEl.textContent = '一覧を取得できませんでした。再度お試しください';
  }
}
document.getElementById('q').addEventListener('input', (e) => load(e.target.value.trim()));
load('');
```
- `status` は `window.status` と紛らわしいので `statusEl` に改名しています。
- 前後の空白は `trim()` で除きます。

**書き込みと実行が使える状態で再開したときの手順**
1. 変更の依頼なので、ASC の手順どおり専用の worktree と branch（Issue #12）で作業します。
2. 上の変更を入れます。
3. `npm run dev` で起動し、ブラウザで次を確認します。
   - 部分一致で一覧が絞り込まれること。
   - 一致しない文字列で「該当するユーザーはいません」が出ること。
   - 入力を消すと全件に戻ること。
4. 独立レビューを受けたうえで、commit、push、PR の提出まで進めます。

**merge はしません**
`docs/requirements.md` を見ると、「来月のリリースに入れたい」という話の優先度は未確認です。merge の許可もまだありません。

編集と実行のツールを有効にして再実行していただければ、続きから進めます。

